import React from 'react';
import './Item.css'; 

const Item = ({language, logo}) => {
  return (
    <div className="item">
      <img src={logo} alt={language} className="item-image" />
      <p className = "itemtext">{language}</p>
    </div>
  );
};

export default Item;
